<script setup lang="ts">
import type { Project } from '~~/shared/types/projects'
import type { ProjectCounterparty } from '~~/shared/types/estimate'
import { useQueryClient } from '@tanstack/vue-query'
import type { ProjectEstimate } from '~~/shared/types/estimate'
const props = defineProps<{ project: Project; ownOnly?: boolean }>()
const { query } = useProjectEstimateData(() => props.project.id)
const { query: catalog, refresh: refreshCatalog } = useProjectCompanies(() => props.project.id)
const queryClient = useQueryClient()
const allParties = computed(() => query.data.value?.counterparties ?? [])
const parties = computed(() => allParties.value.filter(party => !!party.isOwnLegalEntity === !!props.ownOnly))
const editable = computed(() => props.project.permission !== 'viewer'), open = ref(false), selectorOpen = ref(false), busy = ref(false), error = ref(''), selectionKind = computed(() => !!props.ownOnly), search = ref(''), revision = ref(0)
const selected = ref<ProjectCounterparty | null>(null)
const exporting = ref(''), exportError = ref(''), auth = useAuthStore(), supabase = useNuxtApp().$supabase
const candidates = computed(() => catalog.data.value?.filter(row => row.isOwnLegalEntity === selectionKind.value && `${row.company} ${row.inn}`.toLocaleLowerCase('ru').includes(search.value.trim().toLocaleLowerCase('ru'))) ?? [])
const fields = [{ key: 'company', label: 'Компания' },{key:'inn',label:'ИНН'},{key:'kpp',label:'КПП'},{key:'director',label:'Директор'},{key:'address',label:'Адрес'},{key:'bankAccount',label:'Р/с'}] as const
function show(party: ProjectCounterparty) { selected.value = party; revision.value = query.data.value?.revision ?? 0; error.value = ''; open.value = true }
function used(id: string) { return query.data.value?.items.some(item => item.counterpartyId === id) }
async function choose() { revision.value = query.data.value?.revision ?? 0; search.value = ''; error.value = ''; selectorOpen.value = true; await catalog.refetch() }
async function link(id: string, remove = false) {
 if (!editable.value || busy.value) return
 busy.value = true; error.value = ''; const userId = auth.user?.id
 try { const result = await sharedRequest<ProjectEstimate>(`/api/projects/${props.project.id}/companies`,{method:remove?'DELETE':'PUT',body:{catalogId:id,revision:revision.value}}); if(auth.user?.id!==userId)return; queryClient.setQueryData(['account',userId,'project-estimate',props.project.id],result); open.value = false; selectorOpen.value = false; await refreshCatalog() }
 catch(failure:any){ error.value = failure?.data?.message || failure.message; if(failure?.statusCode===409)await query.refetch() }
 finally { busy.value = false }
}
watch(editable, allowed => { if (!allowed) { open.value = false; selectorOpen.value = false } })
async function download(format: 'xlsx' | 'pdf') {
  if (exporting.value) return
  exporting.value = format; exportError.value = ''; const userId = auth.user?.id
  try {
    const { data } = await supabase.auth.getSession()
    if (!data.session || data.session.user.id !== userId) throw Error('Войдите в аккаунт')
    const blob = await $fetch<Blob>(`/api/projects/${props.project.id}/estimate-export`, { method: 'POST', retry: 0, responseType: 'blob', headers: { Authorization: `Bearer ${data.session.access_token}` }, body: { target: 'counterparties', companyKind: props.ownOnly ? 'legal-entities' : 'counterparties', format, view: { hiddenRows: [], hiddenColumns: [] } } })
    if (auth.user?.id !== userId) return
    const url = URL.createObjectURL(blob), link = document.createElement('a')
    link.href = url; link.download = `${props.ownOnly ? 'Наши юр. лица' : 'Контрагенты'} — ${props.project.name.replace(/[\\/:*?"<>|]/g, '-')}.${format}`; document.body.appendChild(link); link.click(); link.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 10000)
  } catch (failure: any) {
    if (failure?.data instanceof Blob) { try { exportError.value = JSON.parse(await failure.data.text()).message } catch { exportError.value = 'Не удалось скачать файл' } }
    else exportError.value = failure?.data?.message || failure.message
  } finally { exporting.value = '' }
}
</script>
<template>
  <section class="project-page-members counterparties-section" :aria-label="ownOnly ? 'Наши юридические лица проекта' : 'Контрагенты проекта'"><div class="project-page-section-heading"><h2>{{ownOnly ? 'Наши Юр. лица' : 'Контрагенты'}} <span class="party-count">{{ parties.length }}</span></h2><div v-if="!query.isPending.value && !query.error.value" class="party-export-actions"><UButton label="Excel" :aria-label="ownOnly ? 'Экспорт наших юрлиц в Excel' : 'Экспорт контрагентов в Excel'" icon="i-lucide-file-spreadsheet" color="neutral" variant="outline" :loading="exporting === 'xlsx'" :disabled="!!exporting" @click="download('xlsx')"/><UButton label="PDF" :aria-label="ownOnly ? 'Экспорт наших юрлиц в PDF' : 'Экспорт контрагентов в PDF'" icon="i-lucide-file-text" color="neutral" variant="outline" :loading="exporting === 'pdf'" :disabled="!!exporting" @click="download('pdf')"/><UButton v-if="editable" label="Выбрать из общей базы" icon="i-lucide-plus" color="neutral" variant="outline" :disabled="parties.length >= 200" @click="choose"/></div></div><UAlert v-if="exportError" color="error" :description="exportError" class="mb-4"/>
    <p v-if="query.isPending.value" class="party-muted">Загружаем контрагентов…</p><UAlert v-else-if="query.error.value" color="error" title="Не удалось загрузить контрагентов" :actions="[{ label: 'Повторить', onClick: () => query.refetch() }]"/>
    <template v-else><p v-if="!parties.length" class="party-muted">{{ownOnly ? 'Выберите наши юридические лица из общей базы.' : 'Выберите контрагентов из общей базы.'}} Компании будут доступны в смете проекта.</p><div v-else class="party-grid"><button v-for="party in parties" :key="party.id" type="button" class="party-card" @click="show(party)"><span class="party-icon"><UIcon :name="ownOnly?'i-lucide-landmark':'i-lucide-building-2'"/></span><span v-if="party.isOwnLegalEntity" class="party-own">Наше юр. лицо</span><strong>{{ party.company }}</strong><small v-if="party.inn">ИНН {{ party.inn }}</small><small v-if="party.director">{{ party.director }}</small><span class="party-card-link">Реквизиты →</span></button></div>
    </template>
  </section>
  <UModal v-model:open="open" :title="selected?.company || 'Реквизиты'" description="Реквизиты используются из общей базы компаний." :dismissible="!busy" :ui="{content:'sm:max-w-2xl'}"><template #body><span v-if="selected?.isOwnLegalEntity" class="party-own">Наше юр. лицо</span><dl v-if="selected" class="party-details"><div v-for="field in fields" :key="field.key"><dt>{{field.label}}</dt><dd>{{selected[field.key] || '—'}}</dd></div></dl><p v-if="selected && used(selected.id)" class="party-muted">Компания используется в смете. Сначала измените привязки позиций, чтобы убратьить её из проекта.</p><UAlert v-if="error" color="error" :description="error"/></template><template #footer><div class="party-footer"><UButton v-if="editable && selected?.catalogId" label="Убрать из проекта" color="error" variant="ghost" :disabled="busy || used(selected.id)" @click="link(selected.catalogId!,true)"/><UButton v-if="selected?.catalogId" label="Открыть в общей базе" color="neutral" variant="outline" :to="{path:'/projects',query:{tab:selected.isOwnLegalEntity?'legal-entities':'counterparties',company:selected.catalogId}}"/><UButton label="Закрыть" color="neutral" variant="outline" :disabled="busy" @click="open=false"/></div></template></UModal>
  <UModal v-model:open="selectorOpen" :title="ownOnly ? 'Выбрать наше юр. лицо' : 'Выбрать контрагента'" description="Выберите компанию из общей базы." :dismissible="!busy" :ui="{content:'sm:max-w-3xl'}"><template #body><UInput v-model="search" icon="i-lucide-search" placeholder="Компания или ИНН" aria-label="Поиск в общей базе" class="w-full mb-4"/><UAlert v-if="error || catalog.error.value" color="error" :description="error || 'Не удалось загрузить общую базу'"/><p v-if="catalog.isPending.value" class="party-muted">Загрузка…</p><div v-else class="party-choices"><div v-for="company in candidates" :key="company.id"><span><strong>{{company.company}}</strong><small>ИНН {{company.inn || 'не указан'}}</small><small v-if="company.isOwnLegalEntity" class="party-own">Наше юр. лицо</small></span><UButton :label="allParties.some(party=>party.catalogId===company.id)?'Уже в проекте':'Выбрать'" color="neutral" variant="outline" :disabled="busy || allParties.some(party=>party.catalogId===company.id)" @click="link(company.id)"/></div><p v-if="!candidates.length" class="party-muted">Компаний пока нет или они не найдены.</p></div></template><template #footer><div class="party-footer"><UButton label="Общая база компаний" color="neutral" variant="outline" :to="selectionKind?'/projects?tab=legal-entities':'/projects?tab=counterparties'"/><UButton label="Закрыть" color="neutral" variant="outline" :disabled="busy" @click="selectorOpen=false"/></div></template></UModal>
</template>
<style scoped>
.party-details{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:24px 0}.party-details>div:first-child,.party-details>div:nth-child(5){grid-column:1/-1}.party-details dt{font-size:12px;color:#94a3b8;margin-bottom:6px}.party-details dd{font-size:14px;color:#475569;overflow-wrap:anywhere}.party-own{display:inline-block;border-radius:7px;padding:5px 8px;color:var(--ui-primary);background:#f3f4f8;font-size:11px}.party-selector-tabs{display:flex;gap:8px;margin-bottom:20px;padding:5px;background:#edf0f5;border-radius:12px}.party-selector-tabs button{padding:10px 14px;border-radius:8px;color:#8292a8;font-size:13px;cursor:pointer}.party-selector-tabs button[aria-pressed=true]{background:white;color:#334155}.party-choices>div{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:16px 0;border-bottom:1px solid #e2e8f0}.party-choices>div>span{display:flex;flex-direction:column;gap:6px;align-items:flex-start;min-width:0}.party-choices strong{font-size:14px;color:#475569;overflow-wrap:anywhere}.party-choices small{font-size:12px;color:#94a3b8}.party-export-actions{display:flex;gap:8px;flex-wrap:wrap}.counterparties-section{margin-bottom:32px}.party-count{font-size:14px;color:#94a3b8;font-weight:400;margin-left:8px}.party-muted{color:#94a3b8;font-size:13px;line-height:1.7}.party-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px;margin:24px 0}.party-card{text-align:left;border:1px solid #e2e8f0;border-radius:16px;padding:20px;display:flex;flex-direction:column;align-items:flex-start;gap:10px;background:#fff;min-width:0;cursor:pointer}.party-card:hover{border-color:var(--ui-primary)}.party-card strong{font-size:16px;color:#334155;overflow-wrap:anywhere}.party-card small{color:#94a3b8;overflow-wrap:anywhere;font-size:12px}.party-icon{display:grid;place-items:center;width:40px;height:40px;background:#f3f4f8;border-radius:12px;color:var(--ui-primary)}.party-card-link{font-size:12px;color:var(--ui-primary);margin-top:10px}.party-form{display:grid;grid-template-columns:1fr 1fr;gap:20px}.party-form label{display:flex;flex-direction:column;gap:8px;color:#475569;font-size:13px}.party-form label:first-child,.party-form label:nth-child(5),.party-form>p,.party-form>[role=alert]{grid-column:1/-1}.party-form input{border:1px solid #cbd5e1;background:white;border-radius:8px;padding:10px 12px;width:100%;min-width:0;outline-color:var(--ui-primary)}.party-footer{display:flex;gap:12px;justify-content:flex-end;flex-wrap:wrap;width:100%}@media(max-width:600px){.party-form{grid-template-columns:1fr}.party-grid{grid-template-columns:1fr}.project-page-section-heading{flex-wrap:wrap;gap:16px}}
</style>
